using System;using System.IO;using System.Linq;using System.Text;using System.Text.Json;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using ImageMagick;using System.Windows.Media.Imaging;
namespace gazegallery;
public sealed class MediaMetadata {
 public string Title{get;set;}="";public string Subject{get;set;}="";public int Rating{get;set;}public string Tags{get;set;}="";public string Comments{get;set;}="";
 public string Technical{get;set;}="";public string Exif{get;set;}="";
 public static string Sidecar(string file)=>file+".gazegallery-metadata.json";
 public static MediaMetadata Read(string file){var value=new MediaMetadata();var info=new FileInfo(file);value.Technical=$"Modified: {info.LastWriteTime:g}\nFile size: {(info.Length>=1048576?$"{info.Length/1048576.0:0.##} MB":$"{info.Length/1024.0:0.##} KB")}";if(!VideoThumbnails.IsVideo(file)){try{using var image=new MagickImage();image.Ping(file);double dx=image.Density.X,dy=image.Density.Y;bool inferred=dx<=0||dy<=0||image.Density.Units==DensityUnit.Undefined;if(image.Density.Units==DensityUnit.PixelsPerCentimeter){dx*=2.54;dy*=2.54;}if(inferred)dx=dy=96;int channels=image.ColorType is ColorType.Grayscale or ColorType.Bilevel?1:image.ColorType is ColorType.GrayscaleAlpha?2:image.HasAlpha?4:3;int bits=(int)image.Depth*channels;try{using var stream=File.OpenRead(file);var decoder=BitmapDecoder.Create(stream,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.None);var frame=decoder.Frames[0];bits=frame.Format.BitsPerPixel;if(inferred&&frame.DpiX>0&&frame.DpiY>0){dx=frame.DpiX;dy=frame.DpiY;}}catch{}value.Technical+=$"\n{image.Width} × {image.Height} px · {dx:0.#} × {dy:0.#} DPI{(inferred?" (default when unspecified)":"")}\n{bits} bits/pixel · {image.Depth} bits/channel · {image.ColorSpace}";var exif=image.GetExifProfile();if(exif!=null){string Bytes(ExifTag<byte[]> tag){var bytes=exif.GetValue(tag)?.Value;return bytes==null?"":Encoding.Unicode.GetString(bytes).TrimEnd('\0');}value.Title=Bytes(ExifTag.XPTitle);value.Subject=Bytes(ExifTag.XPSubject);value.Tags=Bytes(ExifTag.XPKeywords);value.Comments=Bytes(ExifTag.XPComment);value.Rating=exif.GetValue(ExifTag.Rating)?.Value??0;value.Exif=string.Join("\n",exif.Values.Select(v=>v.Tag+": "+(v.GetValue() is byte[] data?Convert.ToHexString(data):v.GetValue()?.ToString())));}}catch(Exception e){value.Exif="EXIF unavailable: "+e.Message;}}
  if(File.Exists(Sidecar(file)))try{var saved=JsonSerializer.Deserialize<MediaMetadata>(File.ReadAllText(Sidecar(file)));if(saved!=null){value.Title=saved.Title;value.Subject=saved.Subject;value.Rating=saved.Rating;value.Tags=saved.Tags;value.Comments=saved.Comments;}}catch{}return value;
 }
 // Replace EXIF APP1 only. The compressed JPEG scan and all other segments remain
 // byte-for-byte intact, avoiding a lossy image encode for a metadata edit.
 public static byte[] JpegBytes(string file,MediaMetadata value){using var image=new MagickImage();image.Ping(file);var profile=image.GetExifProfile()??new ExifProfile();byte[] Text(string s)=>Encoding.Unicode.GetBytes(s+"\0");profile.SetValue(ExifTag.XPTitle,Text(value.Title));profile.SetValue(ExifTag.XPSubject,Text(value.Subject));profile.SetValue(ExifTag.XPKeywords,Text(value.Tags));profile.SetValue(ExifTag.XPComment,Text(value.Comments));profile.SetValue(ExifTag.Rating,(ushort)Math.Clamp(value.Rating,0,5));byte[] exif=profile.ToByteArray();if(!exif.Take(6).SequenceEqual(new byte[]{69,120,105,102,0,0}))exif=new byte[]{69,120,105,102,0,0}.Concat(exif).ToArray();if(exif.Length>65533)throw new IOException("EXIF data exceeds the JPEG segment limit.");byte[] src=File.ReadAllBytes(file);if(src.Length<4||src[0]!=255||src[1]!=216)throw new IOException("Invalid JPEG.");using var output=new MemoryStream();output.Write(src,0,2);output.WriteByte(255);output.WriteByte(225);int len=exif.Length+2;output.WriteByte((byte)(len>>8));output.WriteByte((byte)len);output.Write(exif);int pos=2;while(pos<src.Length){if(src[pos]!=255)throw new IOException("Invalid JPEG marker.");int start=pos;while(pos<src.Length&&src[pos]==255)pos++;if(pos>=src.Length)break;byte marker=src[pos++];if(marker==218||marker==217){output.Write(src,start,src.Length-start);break;}if(marker==1||marker>=208&&marker<=215){output.Write(src,start,pos-start);continue;}if(pos+2>src.Length)throw new IOException("Incomplete JPEG.");int size=src[pos]*256+src[pos+1];if(size<2||pos+size>src.Length)throw new IOException("Invalid JPEG segment.");bool oldExif=marker==225&&size>=8&&src.AsSpan(pos+2,6).SequenceEqual(new byte[]{69,120,105,102,0,0});if(!oldExif)output.Write(src,start,pos+size-start);pos+=size;}return output.ToArray();}
}
public partial class MainWindow {
 Border metadataPanel=new();string? metadataPath;int metadataEpoch;bool metadataLoading;
 void SetupMetadata(){metadataPanel.Background=new SolidColorBrush(Color.FromArgb(215,30,32,36));metadataPanel.CornerRadius=new CornerRadius(6);metadataPanel.Padding=new Thickness(8);metadataPanel.Width=320;metadataPanel.MaxHeight=550;metadataPanel.HorizontalAlignment=HorizontalAlignment.Right;metadataPanel.VerticalAlignment=VerticalAlignment.Top;metadataPanel.Margin=new Thickness(12,122,24,12);metadataPanel.Visibility=Visibility.Collapsed;metadataPanel.MouseRightButtonUp+=(_,e)=>{var menu=new ContextMenu();CloseOverlayMenu(menu,()=>{Config.MetadataOverlay=false;metadataPanel.Visibility=Visibility.Collapsed;},separator:false);menu.IsOpen=true;e.Handled=true;};root.Children.Add(metadataPanel);}
 async void RefreshMetadata(){metadataPanel.Visibility=Config.MetadataOverlay&&Mode=="viewer"&&!Cropping?Visibility.Visible:Visibility.Collapsed;if(metadataPanel.Visibility!=Visibility.Visible)return;metadataPanel.MaxHeight=Math.Max(80,root.ActualHeight-140);if(metadataLoading||metadataPath==current)return;metadataPath=current;int token=++metadataEpoch;if(current==null){metadataPanel.Child=Ui.Label("No image loaded",12);return;}string file=current;metadataLoading=true;metadataPanel.Child=Ui.Label("Reading metadata…",12);try{var data=await Task.Run(async()=>{using var permit=await LoaderPool.Acquire();return MediaMetadata.Read(file);});if(token!=metadataEpoch||current!=file){metadataPath=null;return;}BuildMetadata(file,data);}catch(Exception e){metadataPanel.Child=Ui.Label(e.Message,11);}finally{metadataLoading=false;}}
 void BuildMetadata(string file,MediaMetadata data){var panel=new StackPanel();panel.Children.Add(Ui.Label("File name",11));var filename=Ui.Input(Path.GetFileName(file));filename.FontSize=11;filename.TextWrapping=TextWrapping.Wrap;filename.MinHeight=40;filename.MaxHeight=48;filename.VerticalScrollBarVisibility=ScrollBarVisibility.Auto;panel.Children.Add(filename);if(VideoThumbnails.IsVideo(file)&&View.Image!=null)data.Technical+=$"\n{View.Image.PixelWidth} × {View.Image.PixelHeight} px · {View.Image.Format.BitsPerPixel} bits/pixel (decoded frame)";panel.Children.Add(Ui.Label(data.Technical,11));if(!VideoThumbnails.IsVideo(file)){var analysis=Ui.Label("",11);var analyze=Ui.Button("Analyze unique colors / JPEG quality",()=>{});analyze.Click+=async(_,_)=>{analyze.IsEnabled=false;analysis.Text="Analyzing…";try{string result=await LoaderPool.Run(()=>{using var image=new MagickImage(file);string text=$"Unique colors (decoded image): {image.TotalColors:N0}";if(System.IO.Path.GetExtension(file).ToLowerInvariant() is ".jpg" or ".jpeg")text+=$"\nEstimated JPEG quality: {image.Quality}";return text;});analysis.Text=result;}catch(Exception e){analysis.Text=e.Message;}finally{analyze.IsEnabled=true;}};panel.Children.Add(analyze);panel.Children.Add(analysis);}var fields=new Dictionary<string,TextBox>();foreach(var pair in new[]{("Title",data.Title),("Subject",data.Subject),("Rating (0–5)",data.Rating.ToString()),("Tags",data.Tags),("Comments",data.Comments)}){panel.Children.Add(Ui.Label(pair.Item1,11));var input=Ui.Input(pair.Item2);input.FontSize=11;input.Padding=new Thickness(4);fields[pair.Item1]=input;panel.Children.Add(input);}var ext=Path.GetExtension(file).ToLowerInvariant();panel.Children.Add(Ui.Label(ext is ".jpg" or ".jpeg"?"Descriptive fields are saved in JPEG EXIF.":"Descriptive fields use a companion .gazegallery-metadata.json file to preserve image data.",10));var exif=Ui.Label(data.Exif.Length==0?"No EXIF data":data.Exif,10);panel.Children.Add(new Expander{Header="Full EXIF data",Foreground=Ui.Fg,Content=exif});var save=Ui.Button("Save",()=>Run(async()=>{if(!int.TryParse(fields["Rating (0–5)"].Text,out int rating)||rating<0||rating>5){Toast("Rating must be 0–5");return;}var name=filename.Text.Trim();if(string.IsNullOrWhiteSpace(name)||name.IndexOfAny(Path.GetInvalidFileNameChars())>=0||!Path.GetExtension(name).Equals(Path.GetExtension(file),StringComparison.OrdinalIgnoreCase)){Toast("Choose a valid filename with the same extension");return;}string target=Path.Combine(Path.GetDirectoryName(file)!,name);if(!target.Equals(file,StringComparison.OrdinalIgnoreCase)&&File.Exists(target)){Toast("That filename already exists");return;}data.Title=fields["Title"].Text;data.Subject=fields["Subject"].Text;data.Rating=rating;data.Tags=fields["Tags"].Text;data.Comments=fields["Comments"].Text;if(Operations.Busy)return;var entry=new UndoEntry{Navigation=navigation,Viewed=file};Operations.Busy=true;try{if(ext is ".jpg" or ".jpeg"){var bytes=await Task.Run(()=>MediaMetadata.JpegBytes(file,data));entry.Changes.Add(await Operations.ReplaceBytes(file,bytes));}else{var bytes=Encoding.UTF8.GetBytes(JsonSerializer.Serialize(data,new JsonSerializerOptions{WriteIndented=true}));string sidecar=MediaMetadata.Sidecar(file);if(File.Exists(sidecar))entry.Changes.Add(await Operations.ReplaceBytes(sidecar,bytes));else{await File.WriteAllBytesAsync(sidecar,bytes);entry.Changes.Add(new Change("created-file",sidecar,sidecar));}}
  if(!target.Equals(file,StringComparison.OrdinalIgnoreCase)){await StopVideo();entry.Changes.Add(await Operations.Move(file,target,false));string oldSidecar=MediaMetadata.Sidecar(file);if(File.Exists(oldSidecar))entry.Changes.Add(await Operations.Move(oldSidecar,MediaMetadata.Sidecar(target),false));current=target;}Cache.Clear();await Scan();await ShowIndex(Math.Max(0,Files.IndexOf(current??"")),false);metadataPath=null;Toast("Metadata saved — Ctrl+Z to undo");}finally{Operations.Commit(entry);Operations.Busy=false;}}));save.FontSize=11;panel.Children.Add(save);metadataPanel.Child=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};}
}
